-- Generated by demo-datagen (Main sql, SingleStoreTables): the brokerage world's feeds in SingleStore, for when
-- Kafka is off (D50, amended 2026-11-24, item 238). demo.sh runs it as root after brokerage.sql. Each row is
-- one record of its feed, numbered by seq; brokerage-feeds-pipelines.sql copies each table into the lake.
USE brokerage;
CREATE TABLE IF NOT EXISTS calendar (
  seq BIGINT NOT NULL,
  calendar_date DATE,
  is_business_day TINYINT(1),
  holiday TEXT,
  settlement_date DATE,
  is_month_end TINYINT(1),
  PRIMARY KEY (seq),
  SHARD KEY (seq));
CREATE TABLE IF NOT EXISTS securities (
  seq BIGINT NOT NULL,
  security_id BIGINT,
  symbol TEXT,
  name TEXT,
  security_type TEXT,
  sector TEXT,
  cusip TEXT,
  isin TEXT,
  currency_id BIGINT,
  listed_on TEXT,
  unit_exponent INT,
  PRIMARY KEY (seq),
  SHARD KEY (seq));
CREATE TABLE IF NOT EXISTS chart_of_accounts (
  seq BIGINT NOT NULL,
  definition_id INT,
  parent_id INT,
  code TEXT,
  name TEXT,
  natural_class TEXT,
  measure TEXT,
  level TEXT,
  normal_side TEXT,
  may_reverse TINYINT(1),
  key_dimensions TEXT,
  description TEXT,
  PRIMARY KEY (seq),
  SHARD KEY (seq));
CREATE TABLE IF NOT EXISTS booking_schemes (
  seq BIGINT NOT NULL,
  booking_scheme_id INT,
  name TEXT,
  template_id INT,
  template_name TEXT,
  calculations INT,
  journal_lines INT,
  note TEXT,
  PRIMARY KEY (seq),
  SHARD KEY (seq));
CREATE TABLE IF NOT EXISTS accounts (
  seq BIGINT NOT NULL,
  brokerage_account BIGINT,
  account_kind TEXT,
  persona TEXT,
  opened_on DATE,
  disposal_method TEXT,
  base_currency_id BIGINT,
  status TEXT,
  PRIMARY KEY (seq),
  SHARD KEY (seq));
CREATE TABLE IF NOT EXISTS bars_5m (
  seq BIGINT NOT NULL,
  security_id BIGINT,
  symbol TEXT,
  bar_start DATETIME(6),
  business_date DATE,
  open DECIMAL(18, 4),
  high DECIMAL(18, 4),
  low DECIMAL(18, 4),
  close DECIMAL(18, 4),
  volume BIGINT,
  PRIMARY KEY (seq),
  SHARD KEY (seq));
CREATE TABLE IF NOT EXISTS prices_eod (
  seq BIGINT NOT NULL,
  business_date DATE,
  security_id BIGINT,
  symbol TEXT,
  close_price DECIMAL(18, 2),
  currency_id BIGINT,
  PRIMARY KEY (seq),
  SHARD KEY (seq));
CREATE TABLE IF NOT EXISTS financial_transactions (
  seq BIGINT NOT NULL,
  financial_transaction_id BIGINT,
  template_id INT,
  template_name TEXT,
  booking_scheme_id INT,
  brokerage_account BIGINT,
  security_id BIGINT,
  currency_id BIGINT,
  quantity DECIMAL(18, 5),
  originating_financial_transaction_id BIGINT,
  effective_date DATE,
  originator TEXT,
  business_date DATE,
  event_time DATETIME(6),
  amount DECIMAL(18, 2),
  payment_id TEXT,
  expected_settlement_date DATE,
  good_faith_amount DECIMAL(18, 2),
  order_id TEXT,
  estimated_amount DECIMAL(18, 2),
  estimated_price DECIMAL(18, 6),
  fill_id TEXT,
  fill_price DECIMAL(18, 6),
  fill_amount DECIMAL(18, 2),
  trade_date DATE,
  venue TEXT,
  settled_amount DECIMAL(18, 2),
  settlement_date DATE,
  gross_amount DECIMAL(18, 2),
  sec_fee DECIMAL(18, 2),
  finra_taf DECIMAL(18, 2),
  lots JSON,
  total_fees DECIMAL(18, 2),
  released_amount DECIMAL(18, 2),
  period_start DATE,
  period_end DATE,
  rate DECIMAL(9, 6),
  average_debit_balance DECIMAL(18, 2),
  accrued_through_date DATE,
  locate_id TEXT,
  PRIMARY KEY (seq),
  SHARD KEY (seq));
CREATE TABLE IF NOT EXISTS journal_lines (
  seq BIGINT NOT NULL,
  journal_line_id BIGINT,
  financial_transaction_id BIGINT,
  line_number INT,
  booking_scheme_id INT,
  template_id INT,
  sub_ledger_id INT,
  sub_ledger TEXT,
  definition_id INT,
  definition_name TEXT,
  ledger_account_id BIGINT,
  brokerage_account BIGINT,
  currency_id BIGINT,
  security_id BIGINT,
  lot BIGINT,
  measure TEXT,
  side TEXT,
  amount DECIMAL(20, 5),
  effective_date DATE,
  business_date DATE,
  event_time DATETIME(6),
  PRIMARY KEY (seq),
  SHARD KEY (seq));
CREATE TABLE IF NOT EXISTS posting_rejections (
  seq BIGINT NOT NULL,
  financial_transaction_id BIGINT,
  template_id INT,
  template_name TEXT,
  brokerage_account BIGINT,
  originating_financial_transaction_id BIGINT,
  reason TEXT,
  detail TEXT,
  business_date DATE,
  event_time DATETIME(6),
  PRIMARY KEY (seq),
  SHARD KEY (seq));
CREATE TABLE IF NOT EXISTS balances_eod (
  seq BIGINT NOT NULL,
  business_date DATE,
  brokerage_account BIGINT,
  ledger_account_id BIGINT,
  sub_ledger TEXT,
  definition_id INT,
  definition_name TEXT,
  security_id BIGINT,
  lot BIGINT,
  measure TEXT,
  normal_side TEXT,
  balance DECIMAL(20, 5),
  PRIMARY KEY (seq),
